package com.lexorion.payroll.service;import com.lexorion.payroll.domain.PayrollWorkspace;import com.lexorion.payroll.repository.PayrollWorkspaceRepository;import com.lexorion.payroll.tenant.*;import org.springframework.stereotype.Component;@Component public class PayrollWorkspaceScope{private final TrustedPayrollContextHolder contexts;private final PayrollWorkspaceRepository workspaces;public PayrollWorkspaceScope(TrustedPayrollContextHolder c,PayrollWorkspaceRepository w){contexts=c;workspaces=w;}public TrustedPayrollContext context(){return contexts.require();}public PayrollWorkspace locked(){var c=context();PayrollWorkspace value=workspaces.findById(c.workspaceId()).orElseGet(()->{PayrollWorkspace w=new PayrollWorkspace();w.setId(c.workspaceId());w.setKey(c.workspaceKey());return workspaces.saveAndFlush(w);});if(!value.getKey().equals(c.workspaceKey()))throw new IllegalStateException("Trusted workspace identity mismatch");return workspaces.findByIdForUpdate(value.getId()).orElseThrow();}}
